```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("liczby.txt");
    int n;
    int ile = 0;
    cout << "a) Liczby z dokladnie 4 dzielnikami:" << endl;
    while (plik >> n) {
        vector<int> dzielniki;
        for (int i = 1; i <= n; i++) {
            if (n % i == 0) dzielniki.push_back(i);
        }
        if ((int)dzielniki.size() == 4) {
            ile++;
            cout << "   " << n << " (dzielniki:";
            for (int d : dzielniki) cout << " " << d;
            cout << ")" << endl;
        }
    }
    cout << "b) Znaleziono: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Dla kazdej liczby zbieramy wszystkie dzielniki do wektora. Jezeli wektor ma dokladnie 4 elementy, wypisujemy liczbe i jej dzielniki.

